import{_ as r}from"./chunks/第一步-03.BbZWR5tM.js";import{_ as t,o as a,c as o,a2 as p}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/img/%E5%A4%A7%E5%B1%8F%E6%89%8B%E5%86%8C/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8.gif",l="/newx-doc/img/%E5%A4%A7%E5%B1%8F%E6%89%8B%E5%86%8C/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.png",d="/newx-doc/img/%E5%A4%A7%E5%B1%8F%E6%89%8B%E5%86%8C/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.png",m="/newx-doc/img/%E5%A4%A7%E5%B1%8F%E6%89%8B%E5%86%8C/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.png",n="/newx-doc/img/%E5%A4%A7%E5%B1%8F%E6%89%8B%E5%86%8C/%E6%8A%A5%E8%A1%A8%E8%AE%BE%E8%AE%A1%E5%99%A8/%E7%AC%AC%E5%9B%9B%E6%AD%A5-JimuReport.png",g=JSON.parse('{"title":"报表设计器","description":"","frontmatter":{},"headers":[],"relativePath":"report.md","filePath":"report.md","lastUpdated":null}'),c={name:"report.md"};function s(u,e,h,A,E,_){return a(),o("div",null,[...e[0]||(e[0]=[p('<h1 id="报表设计器" tabindex="-1">报表设计器 <a class="header-anchor" href="#报表设计器" aria-label="Permalink to &quot;报表设计器&quot;">​</a></h1><p>数据可视化，一般可以通过报表设计器、或者大屏设计器来实现。本小节，我们来讲解报表设计器的功能开启。</p><p>报表设计器，指的是使用 Web 版设计器，通过类似于 Excel 操作风格，通过拖拽完成报表设计。如下图所示：</p><p><img src="'+i+'" alt="报表设计器"></p><p>在项目中，通过集成市面上的报表引擎，实现了报表设计器的能力。目前使用如下：</p><table tabindex="0"><thead><tr><th></th><th>是否集成</th><th>是否开源</th></tr></thead><tbody><tr><td><a href="https://github.com/jeecgboot/JimuReport" target="_blank" rel="noreferrer">JimuReport</a></td><td>已集成</td><td>不开源</td></tr><tr><td><a href="https://gitee.com/anji-plus/report" target="_blank" rel="noreferrer">AJ-Report</a></td><td>集成中</td><td>开源</td></tr><tr><td><a href="https://github.com/youseries/ureport" target="_blank" rel="noreferrer">UReport2</a></td><td>不集成</td><td>开源</td></tr></tbody></table><p>为什么不使用 UReport2 报表引擎呢？</p><p>UReport2 基本处于不维护的状态，最后发版时间是 2018 年！</p><h2 id="_1-功能开启" tabindex="-1">1. 功能开启 <a class="header-anchor" href="#_1-功能开启" aria-label="Permalink to &quot;1. 功能开启&quot;">​</a></h2><p><code>yudao-module-report</code> 实现了报表设计器的能力，考虑到编译速度，默认是关闭的。开启步骤如下：</p><ul><li>第一步，开启 <code>yudao-report-report</code> 模块</li><li>第二步，导入报表的 SQL 数据库脚本</li><li>第三步，启动后端项目，确认功能是否生效</li><li>第四步，启动报表设计器的前端项目</li></ul><h3 id="_1-1-第一步-开启模块" tabindex="-1">1.1 第一步，开启模块 <a class="header-anchor" href="#_1-1-第一步-开启模块" aria-label="Permalink to &quot;1.1 第一步，开启模块&quot;">​</a></h3><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-report</code> 模块的注释。</p><p><img src="'+l+'" alt="引入  模块"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-report</code> 模块。如下图所示：</p><p><img src="'+d+'" alt="引入  依赖"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+r+'" alt="刷新 Maven 依赖"></p><h3 id="_1-2-第二步-导入-sql" tabindex="-1">1.2 第二步，导入 SQL <a class="header-anchor" href="#_1-2-第二步-导入-sql" aria-label="Permalink to &quot;1.2 第二步，导入 SQL&quot;">​</a></h3><p>下载 <a href="https://raw.githubusercontent.com/jeecgboot/jimureport/refs/heads/master/db/jimureport.mysql5.7.create.sql" target="_blank" rel="noreferrer"><code>jimureport.mysql5.7.create.sql</code></a> 脚本，并导入数据库，初始化 JimuReport 相关的表结构和数据。如果你是 Oracle、PostgreSQL 等其它数据库，需要自己使用 Navicat 进行转换。</p><p>友情提示：↑↑↑ jimureport.mysql5.7.create.sql 是可以点击下载的！ ↑↑↑</p><p><img src="'+m+'" alt="导入 SQL 脚本"></p><h3 id="_1-3-第三步-启动后端项目" tabindex="-1">1.3 第三步，启动后端项目 <a class="header-anchor" href="#_1-3-第三步-启动后端项目" aria-label="Permalink to &quot;1.3 第三步，启动后端项目&quot;">​</a></h3><p>启动后端项目，看到 <code>&quot;Init JimuReport Config [ 线程池 ] &quot;</code> 说明开启成功。</p><h3 id="_1-4-第四步-启动前端项目-aj-report" tabindex="-1">1.4 第四步，启动前端项目（AJ-Report） <a class="header-anchor" href="#_1-4-第四步-启动前端项目-aj-report" aria-label="Permalink to &quot;1.4 第四步，启动前端项目（AJ-Report）&quot;">​</a></h3><p>TODO 开发中，预计 4 月份左右。</p><h3 id="_1-4-第四步-启动前端项目-jimureport" tabindex="-1">1.4 第四步，启动前端项目（JimuReport） <a class="header-anchor" href="#_1-4-第四步-启动前端项目-jimureport" aria-label="Permalink to &quot;1.4 第四步，启动前端项目（JimuReport）&quot;">​</a></h3><p>① JimuReport 前端项目内置在后端项目中，无需启动。</p><p>② 访问 [报表管理 -&gt; 报表设计器] 菜单，可以查看对应的功能。如下图所示：</p><p><img src="'+n+'" alt="报表设计"></p><p>可以看到，JimuReport 支持数据报表、图形报表、打印设计等能力。</p><h2 id="_2-如何使用" tabindex="-1">2. 如何使用？ <a class="header-anchor" href="#_2-如何使用" aria-label="Permalink to &quot;2. 如何使用？&quot;">​</a></h2><h3 id="_2-1-aj-report-报表设计器" tabindex="-1">2.1 AJ-Report 报表设计器 <a class="header-anchor" href="#_2-1-aj-report-报表设计器" aria-label="Permalink to &quot;2.1 AJ-Report 报表设计器&quot;">​</a></h3><p>TODO 开发中，预计 4 月份左右。</p><h3 id="_2-2-jimureport-报表设计器" tabindex="-1">2.2 JimuReport 报表设计器 <a class="header-anchor" href="#_2-2-jimureport-报表设计器" aria-label="Permalink to &quot;2.2 JimuReport 报表设计器&quot;">​</a></h3><p>可以查看 JimuReport 的官方文档，主要是：</p><ul><li><a href="http://report.jeecg.com/2075805" target="_blank" rel="noreferrer">快速入门</a></li><li><a href="https://help.jimureport.com/base/new" target="_blank" rel="noreferrer">操作手册（报表设计器）</a></li></ul><p>注意，JimuReport 是商业化的产品，分成免费版、商业版，需要关注下它的 <a href="https://jimureport.com/vip" target="_blank" rel="noreferrer">价格</a> ！！！</p><p>集成 JimuReport 的代码实现？</p><p>① 后端：在 <a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-report/src/main/java/cn/iocoder/yudao/module/report/framework/jmreport" target="_blank" rel="noreferrer"><code>jmreport</code></a> 包下，进行 JimuReport 的集成。</p><p>② 前端：在 <a href="https://github.com/yudaocode/yudao-ui-admin-vue2/blob/master/src/views/report/jmreport/index.vue" target="_blank" rel="noreferrer"><code>@/views/report/jmreport/index.vue</code></a> 文件，通过 IFrame 嵌入 JimuReport 界面。</p><hr><p>星球里，不错的问题：</p><ul><li><a href="https://t.zsxq.com/19s87CV2J" target="_blank" rel="noreferrer">《我想问下积木报表集成里，官方的 yaml 配置参数维护在哪里呀？》</a></li><li><a href="https://t.zsxq.com/Mg9GM" target="_blank" rel="noreferrer">《GoView 使用全局配置设置请求地址为第三方时，出现 404 的 BUG？》</a></li></ul>',44)])])}const q=t(c,[["render",s]]);export{g as __pageData,q as default};
